    ext('apc-resistance','Coagulation','Resistance to activated protein C is', ['Most often caused by a coagulation factor V gene mutation','Always caused by a factor V gene mutation','Always caused by a protein C gene mutation','Associated with a bleeding tendency'],[0],[166],'Factor V Leiden is a major inherited cause of APC resistance and venous thrombophilia. Acquired APC resistance also exists.',['fvl'])
