    ext('protein-c','Coagulation','Protein C', ['After activation, inactivates factors Va and VIIIa','Is vitamin K dependent','Is activated by tissue factor','Is an acute-phase protein','Is produced in the liver'],[0,1,4],[208],'Activated protein C regulates coagulation by inactivating Va/VIIIa; protein C is a liver-produced vitamin-K-dependent anticoagulant.',['hemostasis'],refs('vitamins-lipids-gout',24))
    ext('vwf-role','Coagulation','Von Willebrand factor is important for', ['Preventing protein C hyperactivation and thereby inhibiting fibrinolysis','Platelet contact/adhesion to collagen after vessel-wall injury','Reducing leukocyte activity during fibrinolysis','Activating antithrombin II to prevent coagulation','Protecting factor VIII from plasma degradation'],[1,4],[210],'VWF supports platelet adhesion and stabilizes circulating factor VIII. Those functions explain primary-hemostasis and factor-VIII abnormalities in VWD.',['vwd'])
